# =============================================================================
# STANDARD MODULE: grim_license.sh - Sat Jul 26 02:25:26 PM UTC 2025
# =============================================================================

# Grim License Commands
# Source: tsk_flask/grim_license_manager.py
# Handles: generate, set, validate, upgrade, info, help

grim_license_handler() {
    local command="$1"
    shift
    
    case "$command" in
        "generate")
            if [ -z "$1" ]; then
                echo -e "${RED}❌ Email required. Usage: grim license generate <email> [name]${NC}" >&2
                return 1
            fi
            local email="$1"
            local name="$2"
            
            echo "Executing: grim license generate $*"
            echo -e "${CYAN}🔑 Generating Grim license key for: $email${NC}"
            
            # Call the license manager
            if [ -f "$GRIM_ROOT/tsk_flask/grim_license_manager.py" ]; then
                local result
                if [ -n "$name" ]; then
                    result=$(python3 "$GRIM_ROOT/tsk_flask/grim_license_manager.py" generate --email "$email" --name "$name" 2>/dev/null)
                else
                    result=$(python3 "$GRIM_ROOT/tsk_flask/grim_license_manager.py" generate --email "$email" 2>/dev/null)
                fi
                
                if echo "$result" | grep -q "✅ License generated:"; then
                    local license_key=$(echo "$result" | grep "✅ License generated:" | cut -d' ' -f4)
                    echo -e "${GREEN}✅ License generated: $license_key${NC}"
                    echo -e "${CYAN}📧 Welcome email sent to: $email${NC}"
                    echo ""
                    echo -e "${YELLOW}💡 To use this license:${NC}"
                    echo -e "   grim license set $license_key"
                else
                    echo -e "${RED}❌ Failed to generate license${NC}"
                    echo "$result"
                    return 1
                fi
            else
                echo -e "${RED}❌ License manager not found${NC}" >&2
                return 1
            fi
            ;;
        
        "set")
            if [ -z "$1" ]; then
                echo -e "${RED}❌ License key required. Usage: grim license set <license-key>${NC}" >&2
                return 1
            fi
            local license_key="$1"
            
            echo "Executing: grim license set $*"
            echo -e "${CYAN}🔑 Setting Grim license key...${NC}"
            
            # Set environment variable
            export GRIM_LICENSE_KEY="$license_key"
            
            # Add to .bashrc for persistence
            if ! grep -q "GRIM_LICENSE_KEY" ~/.bashrc; then
                echo "export GRIM_LICENSE_KEY=\"$license_key\"" >> ~/.bashrc
                echo -e "${GREEN}✅ License key saved to ~/.bashrc${NC}"
            else
                # Update existing entry
                sed -i "s/export GRIM_LICENSE_KEY=.*/export GRIM_LICENSE_KEY=\"$license_key\"/" ~/.bashrc
                echo -e "${GREEN}✅ License key updated in ~/.bashrc${NC}"
            fi
            
            echo -e "${GREEN}✅ License key set: $license_key${NC}"
            echo -e "${CYAN}💡 You can now use Grim commands!${NC}"
            ;;
        
        "validate")
            local license_key="${GRIM_LICENSE_KEY:-}"
            if [ -z "$license_key" ]; then
                echo -e "${RED}❌ No license key set. Use: grim license set <license-key>${NC}" >&2
                return 1
            fi
            
            echo "Executing: grim license validate"
            echo -e "${CYAN}🔍 Validating license key...${NC}"
            
            # Call the license manager
            if [ -f "$GRIM_ROOT/tsk_flask/grim_license_manager.py" ]; then
                local result
                result=$(python3 "$GRIM_ROOT/tsk_flask/grim_license_manager.py" validate --license-key "$license_key" 2>/dev/null)
                
                if echo "$result" | grep -q "✅ License valid"; then
                    echo -e "${GREEN}✅ License is valid${NC}"
                    local tier=$(echo "$result" | grep "🎯 Tier:" | cut -d' ' -f3)
                    local email=$(echo "$result" | grep "📧 Email:" | cut -d' ' -f3)
                    echo -e "${CYAN}   Tier: $tier${NC}"
                    echo -e "${CYAN}   Email: $email${NC}"
                else
                    echo -e "${RED}❌ License is invalid${NC}"
                    echo "$result"
                    return 1
                fi
            else
                echo -e "${RED}❌ License manager not found${NC}" >&2
                return 1
            fi
            ;;
        
        "upgrade")
            if [ -z "$1" ]; then
                echo -e "${RED}❌ Target tier required. Usage: grim license upgrade <tier>${NC}" >&2
                echo -e "${YELLOW}Available tiers: PRO, MASTER, REAPER${NC}"
                return 1
            fi
            local target_tier="$1"
            local license_key="${GRIM_LICENSE_KEY:-}"
            
            if [ -z "$license_key" ]; then
                echo -e "${RED}❌ No license key set. Use: grim license set <license-key>${NC}" >&2
                return 1
            fi
            
            echo "Executing: grim license upgrade $*"
            echo -e "${CYAN}⬆️  Upgrading license to $target_tier tier...${NC}"
            
            # Call the license manager
            if [ -f "$GRIM_ROOT/tsk_flask/grim_license_manager.py" ]; then
                local result
                result=$(python3 "$GRIM_ROOT/tsk_flask/grim_license_manager.py" upgrade --license-key "$license_key" --tier "$target_tier" 2>/dev/null)
                
                if echo "$result" | grep -q "✅ License upgraded"; then
                    echo -e "${GREEN}✅ License upgraded to $target_tier${NC}"
                    echo -e "${CYAN}📧 Upgrade confirmation email sent${NC}"
                else
                    echo -e "${RED}❌ Failed to upgrade license${NC}"
                    echo "$result"
                    return 1
                fi
            else
                echo -e "${RED}❌ License manager not found${NC}" >&2
                return 1
            fi
            ;;
        
        "info")
            local license_key="${GRIM_LICENSE_KEY:-}"
            if [ -z "$license_key" ]; then
                echo -e "${RED}❌ No license key set. Use: grim license set <license-key>${NC}" >&2
                return 1
            fi
            
            echo "Executing: grim license info"
            echo -e "${CYAN}📋 License Information:${NC}"
            
            # Call the license manager
            if [ -f "$GRIM_ROOT/tsk_flask/grim_license_manager.py" ]; then
                local result
                result=$(python3 "$GRIM_ROOT/tsk_flask/grim_license_manager.py" info --license-key "$license_key" 2>/dev/null)
                
                if echo "$result" | grep -q "📋 User Information:"; then
                    echo "$result"
                else
                    echo -e "${RED}❌ Failed to get license info${NC}"
                    echo "$result"
                    return 1
                fi
            else
                echo -e "${RED}❌ License manager not found${NC}" >&2
                return 1
            fi
            ;;
        
        "help"|"--help"|"-h")
            echo "Grim License Commands:"
            echo "  grim license generate <email> [name]  - Generate new license key"
            echo "  grim license set <license-key>        - Set your license key"
            echo "  grim license validate                 - Validate current license"
            echo "  grim license upgrade <tier>           - Upgrade license tier"
            echo "  grim license info                     - Show license information"
            echo "  grim license help                     - Show this help"
            echo ""
            echo -e "${YELLOW}Tiers:${NC}"
            echo "  FREE    - Basic features (15 commands)"
            echo "  PRO     - Advanced features (35 commands)"
            echo "  MASTER  - Professional features (60 commands)"
            echo "  REAPER  - Enterprise features (200+ commands)"
            echo ""
            echo -e "${CYAN}Example:${NC}"
            echo "  grim license generate user@example.com"
            echo "  grim license set GRIM-ABC123DEF456"
            echo "  grim license validate"
            echo "  grim license upgrade PRO"
            ;;
        
        "py"|"python")
            py_commands_handler "$@"
            ;;
        *)
            echo "Unknown license command: $command"
            echo "Use 'grim license help' for available commands"
            return 1
            ;;
    esac
} 


