# =============================================================================

# 💀 GRIM INIT: FIRST-RUN EXPERIENCE & REVENUE CONVERTER 💀
# Onboards new users and converts them to Grim Pro

# Handler function for unified system integration
init_command_handler() {
    # This function should only be called when 'grim init' is explicitly used
    # It should not interfere with the main command routing
    show_ascii "grim_skull.txt"
    
    echo -e "${BOLD}${CYAN}════════════════════════════════════════${NC}"
    echo -e "${BOLD}${WHITE}       WELCOME TO THE GRAVEYARD         ${NC}"
    echo -e "${BOLD}${CYAN}════════════════════════════════════════${NC}"
    echo -e "${BLUE}Death comes for all data. But with Grim, resurrection is just a command away.${NC}"
    
    death_pause
    
    collect_user_info
}

set -euo pipefail

# Determine GRIM_ROOT dynamically
if [ -z "${GRIM_ROOT:-}" ]; then
    SCRIPT_PATH="$(readlink -f "${BASH_SOURCE[0]}")"
    GRIM_ROOT="$(dirname "$(dirname "$(dirname "$SCRIPT_PATH")")")"
    export GRIM_ROOT
fi

# Verify GRIM_ROOT exists
if [ ! -d "$GRIM_ROOT" ]; then
    echo "Error: GRIM_ROOT directory not found: $GRIM_ROOT"
    echo "Please set GRIM_ROOT environment variable to the Grim Reaper installation directory"
    exit 1
fi

# ASCII Art and utilities
ASCII_DIR="$GRIM_ROOT/admin/bash_central/ascii"
GRAVEYARD_DIR="$HOME/.graveyard"
USER_DB="$GRAVEYARD_DIR/grim.db"
CONFIG_FILE="$GRAVEYARD_DIR/.rip"

# Colors
RED='\033[0;31m'
GREEN='\033[0;32m'
YELLOW='\033[1;33m'
BLUE='\033[0;34m'
CYAN='\033[0;36m'
PURPLE='\033[0;35m'
WHITE='\033[1;37m'
BOLD='\033[1m'
NC='\033[0m'

# ============================================================================
# UTILITY FUNCTIONS
# ============================================================================
show_ascii() {
    local file="$1"
    if [[ -f "$ASCII_DIR/$file" ]]; then
        cat "$ASCII_DIR/$file"
    else
        # Fallback ASCII art if file not found
        echo -e "${CYAN}"
        echo "    ██████╗ ██████╗ ██╗███╗   ███╗    ██████╗ ███████╗ █████╗ ██████╗ ███████╗██████╗ "
        echo "    ██╔══██╗██╔══██╗██║████╗ ████║    ██╔══██╗██╔════╝██╔══██╗██╔══██╗██╔════╝██╔══██╗"
        echo "    ██║  ██║██████╔╝██║██╔████╔██║    ██████╔╝█████╗  ███████║██████╔╝█████╗  ██████╔╝"
        echo "    ██║  ██║██╔══██╗██║██║╚██╔╝██║    ██╔══██╗██╔══╝  ██╔══██║██╔═══╝ ██╔══╝  ██╔══██╗"
        echo "    ██████╔╝██║  ██║██║██║ ╚═╝ ██║    ██║  ██║███████╗██║  ██║██║     ███████╗██║  ██║"
        echo "    ╚═════╝ ╚═╝  ╚═╝╚═╝╚═╝     ╚═╝    ╚═╝  ╚═╝╚══════╝╚═╝  ╚═╝╚═╝     ╚══════╝╚═╝  ╚═╝"
        echo -e "${NC}"
    fi
    echo ""
}

grim_prompt() {
    local question="$1"
    local default="${2:-}"
    echo ""
    echo -e "${PURPLE}💀${NC} ${WHITE}$question${NC}"
    if [[ -n "$default" ]]; then
        echo -e "${CYAN}   [default: $default]${NC}"
    fi
    echo -ne "${YELLOW} ☠️  ${NC}"
    read -r response
    echo "${response:-$default}"
}

death_pause() {
    echo ""
    echo -e "${RED}Press ENTER to seal your fate...${NC}"
    read -r
}

# ============================================================================
# USER DATA COLLECTION
# ============================================================================
collect_user_info() {
    local name company email role
    
    echo -e "${BOLD}${CYAN}════════════════════════════════════════${NC}"
    echo -e "${BOLD}${WHITE}    WHO SHALL WE PROTECT FROM DEATH?    ${NC}"
    echo -e "${BOLD}${CYAN}════════════════════════════════════════${NC}"
    
    name=$(grim_prompt "What name shall be etched on your digital tombstone?" "Anonymous Grimster")
    company=$(grim_prompt "Which mortal organization do you serve?" "Individual")
    role=$(grim_prompt "What is your role in the realm of the living?" "Developer")
    email=$(grim_prompt "Where shall Death send his notifications?" "")
    
    # Validate email
    while [[ ! "$email" =~ ^[^@]+@[^@]+\.[^@]+$ ]]; do
        echo -e "${RED}💀 Death requires a proper email address to contact you!${NC}"
        email=$(grim_prompt "Enter a valid email address:")
    done
    
    # Generate freemium license key
    echo -e "${BLUE}🔑 Generating your Grim license key...${NC}"
    
    # Use the Grim license manager to generate license
    if [ -f "$GRIM_ROOT/tsk_flask/grim_license_manager.py" ]; then
        license_result=$(python3 "$GRIM_ROOT/tsk_flask/grim_license_manager.py" generate --email "$email" --name "$name" 2>/dev/null)
        
        if echo "$license_result" | grep -q "✅ License generated:"; then
            license_key=$(echo "$license_result" | grep "✅ License generated:" | cut -d' ' -f4)
            echo -e "${GREEN}✅ License generated: $license_key${NC}"
            
            # Set environment variable
            export GRIM_LICENSE_KEY="$license_key"
            echo "export GRIM_LICENSE_KEY=\"$license_key\"" >> ~/.bashrc
            
            # Store in local database
            sqlite3 "$USER_DB" "INSERT OR REPLACE INTO users (name, company, role, email, license_key, created_at) VALUES ('$name', '$company', '$role', '$email', '$license_key', datetime('now'));"
            
            echo -e "${GREEN}✅ Your soul has been recorded in the Grim registry${NC}"
            echo -e "${CYAN}📧 Welcome email sent to: $email${NC}"
            
        else
            echo -e "${YELLOW}⚠️  Could not generate license automatically${NC}"
            echo -e "${CYAN}💡 You can generate a license later with: grim license generate --email $email${NC}"
            
            # Store without license for now
            sqlite3 "$USER_DB" "INSERT OR REPLACE INTO users (name, company, role, email, created_at) VALUES ('$name', '$company', '$role', '$email', datetime('now'));"
        fi
    else
        echo -e "${YELLOW}⚠️  License manager not found${NC}"
        echo -e "${CYAN}💡 You can generate a license later with: grim license generate --email $email${NC}"
        
        # Store without license for now
        sqlite3 "$USER_DB" "INSERT OR REPLACE INTO users (name, company, role, email, created_at) VALUES ('$name', '$company', '$role', '$email', datetime('now'));"
    fi
}

# ============================================================================
# LICENSE GENERATION
# ============================================================================
generate_freemium_license() {
    echo ""
    echo -e "${BOLD}${CYAN}════════════════════════════════════════${NC}"
    echo -e "${BOLD}${WHITE}      GENERATING YOUR LICENSE KEY      ${NC}"
    echo -e "${BOLD}${CYAN}════════════════════════════════════════${NC}"
    
    # Get user email from database
    local user_email=$(sqlite3 "$USER_DB" "SELECT email FROM users ORDER BY created_at DESC LIMIT 1;")
    local user_name=$(sqlite3 "$USER_DB" "SELECT name FROM users ORDER BY created_at DESC LIMIT 1;")
    
    if [ -z "$user_email" ]; then
        echo -e "${RED}❌ User email not found in database${NC}"
        return 1
    fi
    
    echo -e "${CYAN}🔑 Generating freemium license for: $user_email${NC}"
    
    # Call the license manager to generate license
    if [ -f "$GRIM_ROOT/tsk_flask/grim_license_manager.py" ]; then
        local result
        result=$(python3 "$GRIM_ROOT/tsk_flask/grim_license_manager.py" generate --email "$user_email" --name "$user_name" 2>/dev/null)
        
        if echo "$result" | grep -q "✅ License generated:"; then
            local license_key=$(echo "$result" | grep "✅ License generated:" | cut -d' ' -f4)
            
            # Save license key to database
            sqlite3 "$USER_DB" "UPDATE users SET license_key = '$license_key' WHERE email = '$user_email';"
            
            # Set environment variable
            export GRIM_LICENSE_KEY="$license_key"
            
            # Add to .bashrc for persistence
            if ! grep -q "GRIM_LICENSE_KEY" ~/.bashrc; then
                echo "export GRIM_LICENSE_KEY=\"$license_key\"" >> ~/.bashrc
            else
                # Update existing entry
                sed -i "s/export GRIM_LICENSE_KEY=.*/export GRIM_LICENSE_KEY=\"$license_key\"/" ~/.bashrc
            fi
            
            echo -e "${GREEN}✅ License generated and saved: $license_key${NC}"
            echo -e "${CYAN}📧 Welcome email sent to: $user_email${NC}"
            
            # Validate the license
            echo -e "${CYAN}🔍 Validating license with rip.grim.so...${NC}"
            local validation_result
            validation_result=$(python3 "$GRIM_ROOT/tsk_flask/grim_license_manager.py" validate --license-key "$license_key" 2>/dev/null)
            
            if echo "$validation_result" | grep -q "✅ License valid"; then
                echo -e "${GREEN}✅ License validated successfully${NC}"
            else
                echo -e "${YELLOW}⚠️  License validation failed (will retry later)${NC}"
            fi
            
        else
            echo -e "${RED}❌ Failed to generate license${NC}"
            echo "$result"
            return 1
        fi
    else
        echo -e "${RED}❌ License manager not found${NC}"
        return 1
    fi
    
    echo ""
}

