    echo -e "${CYAN}Grim Pro Features:${NC}"
    echo "💎 Full SCYTHE vulnerability scanning"
    echo "💎 Real-time license protection"
    echo "💎 Advanced notification options (Slack, webhooks)"
    echo "💎 Priority support from the Reaper himself"
    echo "💎 Enterprise security features"
    echo ""
    
    local upgrade_choice
    upgrade_choice=$(grim_prompt "Ready to upgrade to Grim Pro? (y/n)" "n")
    
    if [[ "$upgrade_choice" =~ ^[Yy] ]]; then
