        echo -e "${CYAN}Your browser will open shortly...${NC}"
        
        # Try to open browser
        command -v xdg-open >/dev/null && xdg-open "https://grim.so/pay" 2>/dev/null &
        command -v open >/dev/null && open "https://grim.so/pay" 2>/dev/null &
        
        # Mark user as interested in pro
        sqlite3 "$USER_DB" "UPDATE users SET pro_interested = 1, pro_interested_at = datetime('now') WHERE email = (SELECT email FROM users ORDER BY created_at DESC LIMIT 1);"
    else
        echo -e "${RED}💀 Death is patient. We'll remind you when your data dies...${NC}"
        # Set reminder flag
        sqlite3 "$USER_DB" "UPDATE users SET remind_pro = 1 WHERE email = (SELECT email FROM users ORDER BY created_at DESC LIMIT 1);"
    fi
}

# ============================================================================
# SILENT SYSTEM CONFIGURATION
# ============================================================================
setup_hidden_configs() {
    # Create hidden config file in .graveyard/.rip
    mkdir -p "$(dirname "$CONFIG_FILE")"
    
    cat > "$CONFIG_FILE" << EOF
# Grim Reaper Hidden Configuration
# Users can modify these settings if they find this file
[auto_update]
enabled=true
check_interval_min=45
check_interval_max=90
endpoint=https://up.grim.so/version-check

[error_tracking]
enabled=true
anonymous=true
endpoint=https://grim.so/errors/report

[notifications]
enabled=true
method=email

[scythe]
free_limit=3
reminder_frequency=daily
EOF
    
    chmod 600 "$CONFIG_FILE"  # Hidden permissions
    
    echo -e "${GREEN}⚙️ System configured for optimal death prevention${NC}"
}

# ============================================================================
# DATABASE INITIALIZATION
# ============================================================================
init_database() {
    mkdir -p "$GRAVEYARD_DIR"
    
    sqlite3 "$USER_DB" << 'EOF'
CREATE TABLE IF NOT EXISTS users (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL,
    company TEXT,
    role TEXT,
    email TEXT UNIQUE NOT NULL,
    pro_interested INTEGER DEFAULT 0,
    pro_interested_at DATETIME,
    remind_pro INTEGER DEFAULT 0,
    license_key TEXT,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
    last_seen DATETIME DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS scythe_usage (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    user_email TEXT,
    scan_type TEXT,
    results_count INTEGER,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (user_email) REFERENCES users(email)
);

CREATE TABLE IF NOT EXISTS system_events (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    event_type TEXT NOT NULL,
    event_data TEXT,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP
);

-- Insert system initialization event
INSERT INTO system_events (event_type, event_data) VALUES ('grim_init', 'User completed first-run setup');
EOF
}

# ============================================================================
# MAIN INIT FLOW
# ============================================================================
main() {
    # Check if already initialized
    if [[ -f "$USER_DB" ]] && sqlite3 "$USER_DB" "SELECT COUNT(*) FROM users;" 2>/dev/null | grep -q "^[1-9]"; then
        echo -e "${YELLOW}💀 You have already been marked by Death${NC}"
        echo -e "${CYAN}Run 'grim status' to see your current fate${NC}"
        exit 0
    fi
    
    clear
    
    # Show epic intro
    show_ascii "grim-3.txt"
    
    echo -e "${BOLD}${RED}════════════════════════════════════════${NC}"
