    echo -e "${BOLD}${RED}════════════════════════════════════════${NC}"
    
    echo -e "${CYAN}Death comes for all data. But with Grim, resurrection is just a command away.${NC}"
    death_pause
    
    # Initialize database
    init_database
    
    # Phase 1: User Discovery
