    setup_hidden_configs
    
    # Phase 4: Completion
    clear
    show_ascii "skull-1.txt"
    
    echo -e "${BOLD}${GREEN}════════════════════════════════════════${NC}"
    echo -e "${BOLD}${WHITE}      YOUR DATA'S FATE IS SEALED        ${NC}"
    echo -e "${BOLD}${GREEN}════════════════════════════════════════${NC}"
    
    echo ""
    echo -e "${CYAN}💀 Death is patient. Grim is ready.${NC}"
    echo ""
