# =============================================================================
# STANDARD MODULE: license.sh - Sat Jul 26 02:25:26 PM UTC 2025
# =============================================================================

# Grim License Commands
# Handles: generate, validate, upgrade, info, set

license_handler() {
    local command="$1"
    shift
    
    case "$command" in
        "generate")
            if [ -z "$1" ]; then
                echo -e "${RED}❌ Email required. Usage: grim license generate <email> [name]${NC}" >&2
                return 1
            fi
            echo "Executing: grim license generate $*"
            echo -e "${CYAN}🔑 Generating Grim license...${NC}"
            
            local email="$1"
            local name="${2:-}"
            
            if [ -f "$GRIM_ROOT/tsk_flask/grim_license_manager.py" ]; then
                if [ -n "$name" ]; then
                    python3 "$GRIM_ROOT/tsk_flask/grim_license_manager.py" generate --email "$email" --name "$name"
                else
                    python3 "$GRIM_ROOT/tsk_flask/grim_license_manager.py" generate --email "$email"
                fi
            else
                echo -e "${RED}❌ License manager not found${NC}" >&2
                return 1
            fi
            ;;
        
        "validate")
            local license_key="$1"
            if [ -z "$license_key" ]; then
                # Try to get from environment
                license_key="${GRIM_LICENSE_KEY:-}"
                if [ -z "$license_key" ]; then
                    echo -e "${RED}❌ License key required. Usage: grim license validate <license-key>${NC}" >&2
                    echo -e "${YELLOW}💡 Or set GRIM_LICENSE_KEY environment variable${NC}" >&2
                    return 1
                fi
            fi
            
            echo "Executing: grim license validate $license_key"
            echo -e "${CYAN}🔍 Validating Grim license...${NC}"
            
            if [ -f "$GRIM_ROOT/tsk_flask/grim_license_manager.py" ]; then
                python3 "$GRIM_ROOT/tsk_flask/grim_license_manager.py" validate --license-key "$license_key"
            else
                echo -e "${RED}❌ License manager not found${NC}" >&2
                return 1
            fi
            ;;
        
        "upgrade")
            if [ -z "$1" ] || [ -z "$2" ]; then
                echo -e "${RED}❌ License key and tier required. Usage: grim license upgrade <license-key> <tier>${NC}" >&2
                echo -e "${YELLOW}Available tiers: PRO, MASTER, REAPER${NC}" >&2
                return 1
            fi
            echo "Executing: grim license upgrade $*"
            echo -e "${CYAN}🚀 Upgrading Grim license...${NC}"
            
            local license_key="$1"
            local tier="$2"
            local stripe_customer_id="${3:-}"
            
            if [ -f "$GRIM_ROOT/tsk_flask/grim_license_manager.py" ]; then
                if [ -n "$stripe_customer_id" ]; then
                    python3 "$GRIM_ROOT/tsk_flask/grim_license_manager.py" upgrade --license-key "$license_key" --tier "$tier" --stripe-customer-id "$stripe_customer_id"
                else
                    python3 "$GRIM_ROOT/tsk_flask/grim_license_manager.py" upgrade --license-key "$license_key" --tier "$tier"
                fi
            else
                echo -e "${RED}❌ License manager not found${NC}" >&2
                return 1
            fi
            ;;
        
        "info")
            local license_key="$1"
            if [ -z "$license_key" ]; then
                # Try to get from environment
                license_key="${GRIM_LICENSE_KEY:-}"
                if [ -z "$license_key" ]; then
                    echo -e "${RED}❌ License key required. Usage: grim license info <license-key>${NC}" >&2
                    echo -e "${YELLOW}💡 Or set GRIM_LICENSE_KEY environment variable${NC}" >&2
                    return 1
                fi
            fi
            
            echo "Executing: grim license info $license_key"
            echo -e "${CYAN}📋 Getting license information...${NC}"
            
            if [ -f "$GRIM_ROOT/tsk_flask/grim_license_manager.py" ]; then
                python3 "$GRIM_ROOT/tsk_flask/grim_license_manager.py" info --license-key "$license_key"
            else
                echo -e "${RED}❌ License manager not found${NC}" >&2
                return 1
            fi
            ;;
        
        "set")
            if [ -z "$1" ]; then
                echo -e "${RED}❌ License key required. Usage: grim license set <license-key>${NC}" >&2
                return 1
            fi
            echo "Executing: grim license set $1"
            echo -e "${CYAN}🔧 Setting Grim license key...${NC}"
            
            local license_key="$1"
            
            # Set environment variable
            export GRIM_LICENSE_KEY="$license_key"
            echo "export GRIM_LICENSE_KEY=\"$license_key\"" >> ~/.bashrc
            
            # Validate the license
            if [ -f "$GRIM_ROOT/tsk_flask/grim_license_manager.py" ]; then
                validation_result=$(python3 "$GRIM_ROOT/tsk_flask/grim_license_manager.py" validate --license-key "$license_key" 2>/dev/null)
                
                if echo "$validation_result" | grep -q "✅ License valid"; then
                    echo -e "${GREEN}✅ License key set and validated${NC}"
                    echo -e "${CYAN}📧 Email: $(echo "$validation_result" | grep "📧 Email:" | cut -d' ' -f3)${NC}"
                    echo -e "${CYAN}🎯 Tier: $(echo "$validation_result" | grep "🎯 Tier:" | cut -d' ' -f3)${NC}"
                else
                    echo -e "${YELLOW}⚠️  License key set but validation failed${NC}"
                    echo -e "${YELLOW}💡 Check your license key and try again${NC}"
                fi
            else
                echo -e "${GREEN}✅ License key set${NC}"
                echo -e "${YELLOW}⚠️  License manager not found - cannot validate${NC}"
            fi
            ;;
        
        "help"|"--help"|"-h")
            echo -e "${GREEN}Grim License Commands:${NC}"
            echo "  grim license generate <email> [name]  - Generate new freemium license"
            echo "  grim license validate [license-key]  - Validate license (uses GRIM_LICENSE_KEY if not provided)"
            echo "  grim license upgrade <key> <tier>    - Upgrade license to paid tier"
            echo "  grim license info [license-key]      - Get license information"
            echo "  grim license set <license-key>       - Set license key for current session"
            echo "  grim license help                    - Show this help"
            echo ""
            echo -e "${YELLOW}License Key Format:${NC}"
            echo "  GRIM-XXXXXXXX (16 character hex string)"
            echo ""
            echo -e "${YELLOW}Available Tiers:${NC}"
            echo "  FREE    - Basic features (1GB storage, daily backups)"
            echo "  PRO     - Professional features (100GB storage, hourly backups)"
            echo "  MASTER  - Enterprise features (1TB storage, real-time backup)"
            echo "  REAPER  - Ultimate features (unlimited storage, all features)"
            echo ""
            echo -e "${CYAN}Examples:${NC}"
            echo "  grim license generate user@example.com"
            echo "  grim license set GRIM-ABC123DEF456"
            echo "  grim license upgrade GRIM-ABC123DEF456 PRO"
            echo "  grim license info"
            ;;
        
        "py"|"python")
            py_commands_handler "$@"
            ;;
        *)
            echo "Unknown license command: $command"
            echo "Use 'grim license help' for available commands"
            return 1
            ;;
    esac
} 


