# STANDARD MODULE: scanner.sh - Sat Jul 26 02:25:26 PM UTC 2025
# =============================================================================

# Scanner Commands
# Source: go_grim/cmd/scanner/main.go (Go binary) + py_grim/scanner.py (Python) + sh_grim/scan.sh (Bash)
# Handles Go scanner: NewFileScanner(), ScanDirectory(), GetFileInfo(), GetFileHash(), DetectFileType()
# Handles Python scanner: scan(), main()
# Handles Bash scanner: security, malware, vulnerability, compliance, report, help

scanner_handler() {
    local command="$1"
    shift
    
    case "$command" in
        # Go binary commands (file system scanning)
        "scan"|"directory")
            echo "Executing: grim scanner scan $*"
            if [ -f "$GRIM_ROOT/go_grim/build/grim-scanner" ]; then
                "$GRIM_ROOT/go_grim/build/grim-scanner" "$@"
            else
                echo "Error: grim-scanner binary not found. Run 'cd go_grim && make build-all-tools' to build."
                return 1
            fi
            ;;
        "info")
            echo "Executing: grim scanner info $*"
            if [ -f "$GRIM_ROOT/go_grim/build/grim-scanner" ]; then
                "$GRIM_ROOT/go_grim/build/grim-scanner" -path "$1" -summary
            else
                echo "Error: grim-scanner binary not found."
                return 1
            fi
            ;;
        "hash")
            echo "Executing: grim scanner hash $*"
            if [ -f "$GRIM_ROOT/go_grim/build/grim-scanner" ]; then
                "$GRIM_ROOT/go_grim/build/grim-scanner" -path "$1" -hash
            else
                echo "Error: grim-scanner binary not found."
                return 1
            fi
            ;;
        # Python scanner commands
        "py-scan")
            echo "Executing: grim scanner py-scan $*"
            python3 "$GRIM_ROOT/py_grim/scanner.py" "$@"
            ;;
        # Bash security scanner commands
        "security")
            echo "Executing: grim scanner security $*"
            bash "$GRIM_ROOT/sh_grim/scan.sh" security "$@"
            ;;
        "malware")
            echo "Executing: grim scanner malware $*"
            bash "$GRIM_ROOT/sh_grim/scan.sh" malware "$@"
            ;;
        "vulnerability")
            echo "Executing: grim scanner vulnerability $*"
            bash "$GRIM_ROOT/sh_grim/scan.sh" vulnerability "$@"
            ;;
        "compliance")
            echo "Executing: grim scanner compliance $*"
            bash "$GRIM_ROOT/sh_grim/scan.sh" compliance "$@"
            ;;
        "report")
            echo "Executing: grim scanner report $*"
            bash "$GRIM_ROOT/sh_grim/scan.sh" report "$@"
            ;;
        "help"|"--help"|"-h")
            echo "Scanner Commands:"
            echo ""
            echo "File System Scanning (Go):"
            echo "  grim scanner scan <path>        - Multi-threaded file system scan"
            echo "  grim scanner info <path>        - Get file information and summary"
            echo "  grim scanner hash <path>        - Calculate file hashes (MD5/SHA256)"
            echo ""
            echo "Python Security Scanning:"
            echo "  grim scanner py-scan <path>     - Python-based security scanning"
            echo ""
            echo "Security Scanning (Bash):"
            echo "  grim scanner security           - Advanced security scanning"
            echo "  grim scanner malware            - Malware detection scanning"
            echo "  grim scanner vulnerability      - Vulnerability assessment"
            echo "  grim scanner compliance         - Compliance scanning"
            echo "  grim scanner report             - Generate scan report"
            echo ""
            echo "  grim scanner help               - Show this help"
            echo ""
            echo "Options for Go scanner:"
            echo "  -workers N     - Number of worker threads"
            echo "  -depth N       - Maximum scan depth"
            echo "  -types ext     - Filter by file types"
            echo "  -min-size N    - Minimum file size"
            echo "  -max-size N    - Maximum file size"
            echo "  -output file   - Output results to file"
            echo "  -verbose       - Verbose output"
            echo "  -summary       - Generate summary"
            ;;
        "py"|"python")
            py_commands_handler "$@"
            ;;
        *)
            echo "Unknown scanner command: $command"
