# STANDARD MODULE: scythe-tier.sh - Sat Jul 26 02:25:26 PM UTC 2025
# =============================================================================

# Scythe Tier Commands
# Source: scythe/tier/ integration
# Handles: check, status, upgrade, limits, usage, help

scythe_tier_handler() {
    local command="$1"
    shift
    
    # Check if scythe tier system is available
    if [ ! -f "$GRIM_ROOT/py_grim/wl_scythe/tier/tier_check.sh" ]; then
        echo -e "${RED}❌ Scythe tier system not found.${NC}" >&2
        return 1
    fi
    
    case "$command" in
        "check")
            if [ -z "$1" ]; then
                echo -e "${RED}❌ Command required. Usage: grim scythe-tier check <command>${NC}" >&2
                return 1
            fi
            echo "Executing: grim scythe-tier check $*"
            echo -e "${CYAN}🔮 Checking tier access for command: $1${NC}"
            
            # Get current user from grim system
            local user_id=$(get_grim_user_id)
            if [ -z "$user_id" ]; then
                echo -e "${RED}❌ User not authenticated. Run 'grim init' first.${NC}" >&2
                return 1
            fi
            
            # Check tier access with local caching
            local result
            result=$("$GRIM_ROOT/py_grim/wl_scythe/tier/tier_check.sh" "check_access" "$user_id" "$1")
            
            # Parse JSON result
            local allowed=$(echo "$result" | python3 -c "import sys, json; data=json.load(sys.stdin); print(data.get('allowed', False))")
            local message=$(echo "$result" | python3 -c "import sys, json; data=json.load(sys.stdin); print(data.get('message', ''))")
            
            if [ "$allowed" = "True" ]; then
                echo -e "${GREEN}✅ Access granted${NC}"
                return 0
            else
                echo -e "${RED}❌ Access denied${NC}"
                echo -e "${YELLOW}$message${NC}"
                return 1
            fi
            ;;
        "status")
            echo "Executing: grim scythe-tier status"
            echo -e "${CYAN}🔮 Getting tier status...${NC}"
            
            local user_id=$(get_grim_user_id)
            if [ -z "$user_id" ]; then
                echo -e "${RED}❌ User not authenticated. Run 'grim init' first.${NC}" >&2
                return 1
            fi
            
            # Get tier status with local caching
            local result
            result=$("$GRIM_ROOT/py_grim/wl_scythe/tier/tier_check.sh" "get_usage" "$user_id")
            
            # Parse and display status
            echo "$result" | python3 -c "
import sys, json
try:
    data = json.load(sys.stdin)
    if 'error' in data:
        print('❌ Error:', data['error'])
    else:
        print('📊 Tier Status:')
        print(f'  User ID: {data.get(\"user_id\", \"Unknown\")}')
        print(f'  Current Tier: {data.get(\"user_tier\", \"FREE\")}')
        print('  Usage Records:')
        for usage_type, amount in data.get('total_usage', {}).items():
            print(f'    {usage_type}: {amount}')
except Exception as e:
    print('❌ Error parsing status:', str(e))
"
            ;;
        "upgrade")
            if [ -z "$1" ]; then
                echo -e "${RED}❌ Target tier required. Usage: grim scythe-tier upgrade <tier>${NC}" >&2
                echo -e "${YELLOW}Available tiers: PRO, MASTER, REAPER${NC}"
                return 1
            fi
            echo "Executing: grim scythe-tier upgrade $*"
            echo -e "${CYAN}🔮 Upgrading to tier: $1${NC}"
            
            # Get current user
            local user_id=$(get_grim_user_id)
            if [ -z "$user_id" ]; then
                echo -e "${RED}❌ User not authenticated. Run 'grim init' first.${NC}" >&2
                return 1
            fi
            
            # Get current tier
            local current_tier=$(get_grim_user_tier)
            if [ -z "$current_tier" ]; then
                current_tier="FREE"
            fi
            
            # Get upgrade message with local caching
            local result
            result=$("$GRIM_ROOT/py_grim/wl_scythe/tier/tier_check.sh" "upgrade_message" "$current_tier" "$1")
            
            # Parse and display upgrade info
            echo "$result" | python3 -c "
import sys, json
try:
    data = json.load(sys.stdin)
    if 'error' in data:
        print('❌ Error:', data['error'])
    else:
        print('⬆️  Tier Upgrade Information:')
        print(f'  Current Tier: {data.get(\"current_tier\", \"FREE\")}')
        print(f'  Target Tier: {data.get(\"required_tier\", \"Unknown\")}')
        print(f'  Message: {data.get(\"message\", \"No message available\")}')
        print('')
        print('💳 To upgrade, visit: https://grim.so/upgrade')
        print('   or contact support for enterprise pricing.')
except Exception as e:
    print('❌ Error parsing upgrade info:', str(e))
"
            ;;
        "limits")
            if [ -z "$1" ]; then
                echo -e "${RED}❌ Usage type required. Usage: grim scythe-tier limits <type> [amount]${NC}" >&2
                echo -e "${YELLOW}Usage types: storage_gb, alerts_monthly, api_calls, file_size_gb${NC}"
                return 1
            fi
            
            local usage_type="$1"
            local current_usage="${2:-0}"
            
            echo "Executing: grim scythe-tier limits $*"
            echo -e "${CYAN}🔮 Checking usage limits for: $usage_type${NC}"
            
            local user_id=$(get_grim_user_id)
            if [ -z "$user_id" ]; then
                echo -e "${RED}❌ User not authenticated. Run 'grim init' first.${NC}" >&2
                return 1
            fi
            
            # Check limits with local caching
            local result
            result=$("$GRIM_ROOT/py_grim/wl_scythe/tier/tier_check.sh" "check_limits" "$user_id" "$usage_type" "$current_usage")
            
            # Parse and display limits
            echo "$result" | python3 -c "
import sys, json
try:
    data = json.load(sys.stdin)
    if 'error' in data:
        print('❌ Error:', data['error'])
    else:
        print('📊 Usage Limits:')
        print(f'  Usage Type: {data.get(\"usage_type\", \"Unknown\")}')
        print(f'  Current Usage: {data.get(\"current_usage\", 0)}')
        print(f'  Limit: {data.get(\"limit\", 0)}')
        print(f'  Remaining: {data.get(\"remaining\", 0)}')
        print(f'  Allowed: {\"✅ Yes\" if data.get(\"allowed\", False) else \"❌ No\"}')
        if data.get('overage', 0) > 0:
            print(f'  Overage: {data.get(\"overage\", 0)}')
            print(f'  Overage Cost: ${data.get(\"overage_cost\", 0):.2f}')
except Exception as e:
    print('❌ Error parsing limits:', str(e))
"
            ;;
        "usage")
            echo "Executing: grim scythe-tier usage"
            echo -e "${CYAN}🔮 Getting available commands...${NC}"
            
            local user_id=$(get_grim_user_id)
            if [ -z "$user_id" ]; then
                echo -e "${RED}❌ User not authenticated. Run 'grim init' first.${NC}" >&2
                return 1
            fi
            
            # Get available commands with local caching
            local commands_result
            commands_result=$("$GRIM_ROOT/py_grim/wl_scythe/tier/tier_check.sh" "get_commands" "$user_id")
            
            # Parse and display commands
            echo "$commands_result" | python3 -c "
import sys, json
try:
    data = json.load(sys.stdin)
    if 'error' in data:
        print('❌ Error:', data['error'])
    else:
        print('📋 Available Commands:')
        print(f'  Your Tier: {data.get(\"user_tier\", \"FREE\")}')
        print('  Commands:')
        for cmd in data.get('commands', []):
            print(f'    • {cmd}')
        print('')
        print('💡 Use \"grim scythe-tier upgrade <tier>\" to unlock more commands')
except Exception as e:
    print('❌ Error parsing commands:', str(e))
"
            ;;
        "help"|"--help"|"-h")
            echo -e "${GREEN}Scythe Tier Commands:${NC}"
            echo "  grim scythe-tier check <command>     - Check if you can access a command"
            echo "  grim scythe-tier status              - Show your current tier and usage"
            echo "  grim scythe-tier upgrade <tier>      - Get upgrade information"
            echo "  grim scythe-tier limits <type> [amt] - Check usage limits"
            echo "  grim scythe-tier usage               - Show available commands"
            echo "  grim scythe-tier help                - Show this help"
            echo ""
            echo -e "${YELLOW}Tiers:${NC}"
            echo "  FREE   - Basic features (15 commands)"
            echo "  PRO    - Professional features (35 commands) - $20/month"
            echo "  MASTER - Enterprise features (60 commands) - $49/month"
            echo "  REAPER - Unlimited features (200+ commands) - $99/month"
            echo ""
            echo -e "${CYAN}Examples:${NC}"
            echo "  grim scythe-tier check optimize"
            echo "  grim scythe-tier limits storage_gb 5"
            echo "  grim scythe-tier upgrade PRO"
            ;;
        "py"|"python")
            py_commands_handler "$@"
            ;;
        *)
            echo "Unknown scythe-tier command: $command"
            echo "Use 'grim scythe-tier help' for available commands"
            return 1
            ;;
    esac
}

# Helper function to get grim user ID
get_grim_user_id() {
    # Try to get user ID from grim database
    sqlite3 "$HOME/.graveyard/grim.db" "SELECT user_id FROM users WHERE is_active = 1 LIMIT 1;" 2>/dev/null || echo ""
}

# Helper function to get grim user tier
get_grim_user_tier() {
    local user_id=$(get_grim_user_id)
    if [ -z "$user_id" ]; then
        echo "FREE"
        return
    fi
    sqlite3 "$HOME/.graveyard/grim.db" "SELECT tier FROM users WHERE user_id = '$user_id' LIMIT 1;" 2>/dev/null || echo "FREE"
} 


