# Transfer Commands
# Source: go_grim/cmd/transfer/main.go
# Handles: Multi-protocol file transfer with resume capability

transfer_handler() {
    local command="$1"
    shift
    
    case "$command" in
        "upload"|"send")
            echo "Executing: grim transfer upload $*"
            if [ -f "$GRIM_ROOT/go_grim/build/grim-transfer" ]; then
                "$GRIM_ROOT/go_grim/build/grim-transfer" "$@"
            else
                echo "Error: grim-transfer binary not found. Run 'cd go_grim && make build-all-tools' to build."
                return 1
            fi
            ;;
        "download"|"get")
            echo "Executing: grim transfer download $*"
