# STANDARD MODULE: web.sh - Sat Jul 26 02:25:26 PM UTC 2025
# =============================================================================

# Web Services Commands
# Source: py_grim/grim_web/server.py + py_grim/grim_gateway/gateway.py
# Handles: start, stop, restart, status, gateway, api, help

web_handler() {
    local command="$1"
    shift
    
    case "$command" in
        "start")
            echo "Executing: grim web start $*"
            python3 "$GRIM_ROOT/py_grim/grim_web/server.py" "$@" &
            echo "Web server started"
            ;;
        "stop")
            echo "Executing: grim web stop $*"
            pkill -f "grim_web/server.py" 2>/dev/null || true
            pkill -f "grim_gateway/gateway.py" 2>/dev/null || true
            echo "Web services stopped"
            ;;
        "restart")
            echo "Executing: grim web restart $*"
            pkill -f "grim_web/server.py" 2>/dev/null || true
            sleep 2
            python3 "$GRIM_ROOT/py_grim/grim_web/server.py" "$@" &
            echo "Web server restarted"
            ;;
        "gateway")
            echo "Executing: grim web gateway $*"
            python3 "$GRIM_ROOT/py_grim/grim_gateway/gateway.py" "$@" &
            echo "API gateway started"
            ;;
        "api")
            echo "Executing: grim web api $*"
            python3 "$GRIM_ROOT/py_grim/grim_web/app.py" "$@"
            ;;
        "status")
            echo "Executing: grim web status $*"
            echo "=== Grim Web Services Status ==="
            if pgrep -f "grim_web/server.py" > /dev/null; then
                echo "✓ Web Server: Running (PID: $(pgrep -f 'grim_web/server.py'))"
            else
                echo "✗ Web Server: Not running"
            fi
            if pgrep -f "grim_gateway/gateway.py" > /dev/null; then
                echo "✓ API Gateway: Running (PID: $(pgrep -f 'grim_gateway/gateway.py'))"
            else
                echo "✗ API Gateway: Not running"
            fi
            if pgrep -f "grim_monitor/dashboard.py" > /dev/null; then
                echo "✓ Dashboard: Running (PID: $(pgrep -f 'grim_monitor/dashboard.py'))"
            else
                echo "✗ Dashboard: Not running"
            fi
            ;;
        "help"|"--help"|"-h")
            echo "Web Services Commands:"
            echo "  grim web start      - Start main web server (FastAPI)"
            echo "  grim web stop       - Stop all web services"
            echo "  grim web restart    - Restart web server"
            echo "  grim web gateway    - Start API gateway with load balancing"
            echo "  grim web api        - Start API application"
            echo "  grim web status     - Show web services status"
            echo "  grim web help       - Show this help"
            echo ""
            echo "Features:"
            echo "  - FastAPI-based REST API"
            echo "  - TuskLang integration"
            echo "  - API gateway with load balancing"
            echo "  - Real-time monitoring endpoints"
            echo "  - Production-ready deployment"
            echo "  - Graceful shutdown handling"
            ;;
        "py"|"python")
            py_commands_handler "$@"
            ;;
        *)
            echo "Unknown web command: $command"
            echo "Use 'grim web help' for available commands"
            return 1
            ;;
    esac
}


